    listDirectoryEntries: {
        parameters: {
            query?: {
                /**
                 * @description **Busca parcial pelo NOME da entrada**, tolerante a acento e a
                 *     caixa: `veterinaria` acha `Veterinária`.
                 *
                 *     **So o nome, e a escolha e de produto.** Todo outro campo que o
                 *     cartao mostra ja tem controle proprio no topo da mesma tela --
                 *     `city`, `state`, `neighborhood`, `kind` e `verification_level`.
                 *     Fazer `q` casar tambem neles poria dois controles disputando o
                 *     mesmo trabalho e deixaria `applied_filters` ambiguo: a tela nao
                 *     teria como escrever por que uma linha entrou. `about` e o candidato
                 *     conhecido para uma segunda fase, e ele custa um indice proprio
                 *     sobre texto bem maior.
                 *
                 *     **`minLength: 3` nao e gosto.** O indice que atende esta busca e
                 *     GIN de trigrama, e um padrao com menos de tres caracteres nao
                 *     produz trigrama nenhum: a consulta deixa de usar o indice e volta a
                 *     varrer a tabela inteira. O piso e o ponto em que o indice deixa de
                 *     existir. **A tela nao deve enviar `q` antes do terceiro caractere**,
                 *     sob pena de levar 400 no que a pessoa le como o app quebrado.
                 *
                 *     Casa somente sobre `status = 'published'`, como todo o resto da
                 *     operacao. Quem busca por um nome especifico esta testando se ele
                 *     existe, entao um rascunho ou um oculto que aparecesse aqui seria
                 *     resposta a uma pergunta que ninguem tem direito de fazer.
                 */
                q?: string;
                /**
                 * @description **Opcional**, e aqui esta proposta e o contrato divergem de
                 *     proposito. A busca de perdidos comeca com alguem digitando onde
                 *     perdeu; `Perto` e uma aba que abre sozinha, e exigir cidade a
                 *     deixaria vazia ate a pessoa digitar algo. O recorte que falta e
                 *     suprido pela ordenacao por distancia, que e o que a secao promete.
                 *     Sem cidade e sem localizacao valida, `applied_filters` diz
                 *     `scope: all` e a tela sabe que nao esta mostrando "perto" coisa
                 *     nenhuma.
                 */
                city?: string;
                /** @description UF, duas letras. */
                state?: string;
                neighborhood?: string;
                /**
                 * @description Filtra por atividade, UMA por vez (e o chip da tela).
                 *
                 *     Desde 21/10/2026 a entrada tem VARIAS atividades, e este filtro
                 *     passou a ser um teste de PERTINENCIA: a entrada entra no resultado
                 *     quando a atividade pedida esta entre as dela. **A entrada com tres
                 *     atividades aparece nos tres chips e UMA VEZ em cada** -- a consulta
                 *     testa a lista em vez de desdobrar a linha, e por isso `total` nao
                 *     conta a mesma entrada duas vezes.
                 */
                kind?: components["schemas"]["ProfessionalKind"];
                /**
                 * @description Piso, nao igualdade: `contact_verified` traz tambem
                 *     `document_verified`. Filtro por igualdade esconderia o registro
                 *     mais forte de quem pediu o mais fraco.
                 */
                verification_level?: components["schemas"]["VerificationLevel"];
                /**
                 * @description `distance` exige localizacao de referencia valida de quem chama.
                 *     Sem ela, a resposta usa `name` e diz isso em `distance_available`.
                 */
                sort?: "distance" | "name";
                page?: number;
                limit?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /**
             * @description Pagina do diretorio. `total` alimenta "Mostrando 1 a 20 de 87" e
             *     `applied_filters` alimenta a linha que explica o recorte.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["DirectoryEntryPage"];
                };
            };
            400: components["responses"]["ValidationFailed"];
            401: components["responses"]["Unauthorized"];
            429: components["responses"]["TooManyRequests"];
        };
    };
